class Solution {
public:
    vector<string> spellchecker(vector<string>& wordlist, vector<string>& queries) {
        unordered_set<string> exact(wordlist.begin(), wordlist.end());
        unordered_map<string, string> capMap;
        unordered_map<string, string> vowelMap;

        for (const string& w : wordlist) {
            string low = toLower(w);
            if (capMap.find(low) == capMap.end()) {
                capMap[low] = w;
            }
            string dv = devowel(low);
            if (vowelMap.find(dv) == vowelMap.end()) {
                vowelMap[dv] = w;
            }
        }

        vector<string> result;
        result.reserve(queries.size());
        for (const string& q : queries) {
            if (exact.count(q)) {
                result.push_back(q);
                continue;
            }
            string low = toLower(q);
            auto it = capMap.find(low);
            if (it != capMap.end()) {
                result.push_back(it->second);
                continue;
            }
            string dv = devowel(low);
            auto it2 = vowelMap.find(dv);
            if (it2 != vowelMap.end()) {
                result.push_back(it2->second);
            } else {
                result.push_back("");
            }
        }
        return result;
    }
private:
    string toLower(const string& s) {
        string r = s;
        for (char& c : r) {
            if (c >= 'A' && c <= 'Z') c = c - 'A' + 'a';
        }
        return r;
    }
    string devowel(const string& s) {
        string r = s;
        for (char& c : r) {
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                c = '*';
            }
        }
        return r;
    }
};
